queries.cql:
// CrowdStrike CQL for Credential Spray Single Password
// Repository: flame-banking-auth-logs
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count(distinct username) by password_hash > 20 and count(distinct password_hash) by source_ip < 3
event_type="login_attempt"
auth_result="failure"
| groupBy(password_hash, function=[count(as=event_count), collect(username)])
| event_count > 20
| groupBy(source_ip, function=[count(as=event_count), collect(password_hash)])
| event_count < 3
